        "code": "rpg_inventory = ['Легендарный Меч', 'Ржавый Щит', 'Зелье Маны', 'Кольцо невидимости']\n\n# Обращение к массиву памяти происходит за мгновенную сложность O(1)\nprint(rpg_inventory[0])  # Движок моментально вернет 'Легендарный Меч'\n\n# Интегрированная функция len() извлекает метаданные объекта списка без пересчета\nprint(len(rpg_inventory)) # Молниеносно вернет длину: 4 (поскольку объект хранит длину в своей C-структуре)"
