        "code": "original_list = [100, 200, 300]\n\n# Грубая и фатальная ошибка (создает зеркальную ссылку, а не независимую копию!)\nfake_clone = original_list\nfake_clone[0] = 'Взломано!'\nprint(original_list)  # Катастрофа! Исходный список испорчен: ['Взломано!', 200, 300]\n\n# Единственно правильные способы (истинная поверхностная shadow-копия)\ntrue_copy = original_list[:]       # Вариант первый (через магию срезов)\nexplicit_copy = original_list.copy() # Вариант второй (читабельный)"
