          "В Python 3 генератор range() является гениальным образцом так называемой ленивой загрузки (lazy evaluation). Функция работает в формате (start, stop, step), то есть принимает начало, конец и шаг прыжка. Принципиальная архитектурная особенность range в том, что она НЕ строит и НЕ загружает готовый массив в оперативную память вашего компьютера!",
          "Она просто запоминает математическую формулу и генерирует следующее требуемое число 'с нуля', на лету, исключительно в момент вашего запроса. Это сберегает и экономит ценные гигабайты и ресурсы RAM, даже если вы дерзко попросите Python исполнить for x in range(1000000000)."
