          "Директива 'break' — это ваша экстренная красная кнопка катапультирования. Как только считыватель кода наталкивается на заветное слово break, он моментально, жестко и безвозвратно покидает пределы текущего цикла, передавая эстафету следующему блоку кода вне цикла.",
          "Директива 'continue' — это более мягкая кнопка пропуска. Представьте, что вы сканируете текстовые абзацы, и вам нужно обработать только кириллицу. Если вы встречаете латиницу — вы делаете 'continue'. Код НЕ выходит из цикла! Он мгновенно обрывает дальнейшее исполнение ТЕКУЩЕЙ итерации, выкидывает ее и перепрыгивает к оценке следующего по списку элемента коллекции.",
