    "content": "Полиморфизм — это способность объектов разных классов реагировать на один и тот же вызов метода по-разному. В Python это доведено до абсолюта благодаря \"утиной типизации\" (Duck Typing): если объект ходит как утка и крякает как утка, то для Python это утка. Нам не важно, какой именно это класс, нам важно, что у него есть нужный метод.",
