          "Интерпретатор языка оценивает (вычисляет) этот блок кода строго в момент исполнения (Runtime Evaluation). Именно благодаря такой динамической, \"поздней\" связке, язык Python сохраняет свою легендарную гибкость. Вы можете менять логику поведения \"AST: Анатомия Кода\" буквально на лету (Monkey Patching), подстраивая систему под любые, даже самые безумные бизнес-требования заказчика в реальном времени."
